/// This macro has two options for its "Individual matcher" case:
///
/// - `all`: `($signal:ident, $gpio:ident, $af:ident)` - simple case where you only need
///   identifiers, and maybe the function.
/// - group: `(($signal:ident, $group:ident $(, $number:literal)+), $gpio:ident, $af:ident, ($(
///   $lp_input_af:ident => $lp_input_signal:ident )*) ($( $lp_output_af:ident =>
///   $lp_output_signal:ident )*))` - expanded signal case, where you need the number(s) of a
///   signal, or the general group to which the signal belongs. Every expanded branch ends with the
///   pad's LP input and output function groups (empty on chips without an LP GPIO matrix).
///
/// Macro fragments:
///
/// - `$signal`: the name of the signal.
/// - `$group`: the name of the signal, with numbers replaced by placeholders. For `ADC2_CH3` this
///   is `ADCn_CHm`.
/// - `$number`: the numbers extracted from `$signal`.
/// - `$gpio`: the name of the GPIO.
/// - `$af`: the LP IO MUX function, as an identifier (i.e. for function 0 this is `_0`). This is
///   the name of an `LpFunction` variant, and its number is the value to write to the pad's
///   function select field.
/// - `$lp_input_af`: the LP IO MUX function for an LP peripheral input on this pad.
/// - `$lp_input_signal`: the LP peripheral input signal name.
/// - `$lp_output_af`: the LP IO MUX function for an LP peripheral output on this pad.
/// - `$lp_output_signal`: the LP peripheral output signal name.
///
/// Example data:
/// - `(LP_GPIO15, GPIO12, _0)`
/// - `((LP_GPIO15, LP_GPIOn, 15), GPIO12, _0, () ())`
/// - `((LP_GPIO14, LP_GPIOn, 14), GPIO14, _1, () (_0 => LP_UART_TXD))`
/// - `((SAR_I2C_SCL_1, SAR_I2C_SCL_n, 1), GPIO2, _3, () ())`
///
/// The expanded syntax is only available when the signal has at least one numbered component.
#[macro_export]
#[cfg_attr(docsrs, doc(cfg(feature = "_device-selected")))]
macro_rules! for_each_lp_function {
    ($($pattern:tt => $code:tt;)*) => {
        macro_rules! _for_each_inner_lp_function { $(($pattern) => $code;)* ($other : tt)
        => {} } _for_each_inner_lp_function!((all));
    };
}
/// This macro can be used to generate code for each IOMUX digital function of each GPIO.
///
/// IOMUX functions are the alternate digital functions configured via the IO_MUX registers.
/// Use this to implement signal-specific traits for peripherals whose pins must bypass the
/// GPIO matrix (e.g., EMAC, USB).
///
/// For an explanation on the general syntax, as well as usage of individual/repeated
/// matchers, refer to [the crate-level documentation][crate#for_each-macros].
///
/// This macro has two options for its "Individual matcher" case:
///
/// - `all`: `($signal:ident, $gpio:ident, $af:ident)` - simple case where you only need
///   identifiers, and maybe the alternate function.
/// - group: `(($signal:ident, $group:ident $(, $number:literal)+), $gpio:ident, $af:ident)` -
///   expanded signal case, where you need the number(s) of a signal, or the general group to which
///   the signal belongs.
///
/// Macro fragments:
///
/// - `$signal`: the name of the signal.
/// - `$group`: the name of the signal, with numbers replaced by placeholders.
/// - `$number`: the numbers extracted from `$signal`.
/// - `$gpio`: the name of the GPIO.
/// - `$af`: the alternate function number, as an identifier (e.g. `_5`).
///
/// Example data:
/// - `(EMAC_RXD0, GPIO25, _5)`
/// - `((EMAC_RXDn, EMAC_RXDn, 0), GPIO25, _5)`
///
/// The expanded syntax is only available when the signal has at least one numbered component.
#[macro_export]
#[cfg_attr(docsrs, doc(cfg(feature = "_device-selected")))]
macro_rules! for_each_iomux_function {
    ($($pattern:tt => $code:tt;)*) => {
        macro_rules! _for_each_inner_iomux_function { $(($pattern) => $code;)* ($other :
        tt) => {} } _for_each_inner_iomux_function!((FSPIQ, GPIO15, _2));
        _for_each_inner_iomux_function!((FSPICLK, GPIO16, _2));
        _for_each_inner_iomux_function!((FSPID, GPIO17, _2));
        _for_each_inner_iomux_function!((FSPIWP, GPIO18, _2));
        _for_each_inner_iomux_function!((FSPIHD, GPIO19, _2));
        _for_each_inner_iomux_function!((FSPICS0, GPIO20, _2));
        _for_each_inner_iomux_function!((U0RXD, GPIO23, _0));
        _for_each_inner_iomux_function!((U0TXD, GPIO24, _0));
        _for_each_inner_iomux_function!((MTMS, GPIO28, _0));
        _for_each_inner_iomux_function!((MTDI, GPIO29, _0));
        _for_each_inner_iomux_function!((MTCK, GPIO30, _0));
        _for_each_inner_iomux_function!((MTDO, GPIO31, _0));
        _for_each_inner_iomux_function!((FSPICLK, GPIO32, _2));
        _for_each_inner_iomux_function!((FSPID, GPIO33, _2));
        _for_each_inner_iomux_function!((FSPIQ, GPIO36, _2));
        _for_each_inner_iomux_function!((FSPIWP, GPIO37, _2));
        _for_each_inner_iomux_function!((FSPIHD, GPIO38, _2));
        _for_each_inner_iomux_function!((FSPICS0, GPIO39, _2));
        _for_each_inner_iomux_function!(((FSPICS0, FSPICSn, 0), GPIO20, _2));
        _for_each_inner_iomux_function!(((FSPICS0, FSPICSn, 0), GPIO39, _2));
        _for_each_inner_iomux_function!((all(FSPIQ, GPIO15, _2), (FSPICLK, GPIO16, _2),
        (FSPID, GPIO17, _2), (FSPIWP, GPIO18, _2), (FSPIHD, GPIO19, _2), (FSPICS0,
        GPIO20, _2), (U0RXD, GPIO23, _0), (U0TXD, GPIO24, _0), (MTMS, GPIO28, _0), (MTDI,
        GPIO29, _0), (MTCK, GPIO30, _0), (MTDO, GPIO31, _0), (FSPICLK, GPIO32, _2),
        (FSPID, GPIO33, _2), (FSPIQ, GPIO36, _2), (FSPIWP, GPIO37, _2), (FSPIHD, GPIO38,
        _2), (FSPICS0, GPIO39, _2))); _for_each_inner_iomux_function!((FSPICSn((FSPICS0,
        FSPICSn, 0), GPIO20, _2), ((FSPICS0, FSPICSn, 0), GPIO39, _2)));
    };
}
/// Returns the name of the GPIO that provides the given signal, as a string.
///
/// The macro takes the name of a direct function - a digital IO MUX function, an analog
/// function, or an LP IO MUX function - and expands to a string literal like `"GPIO4"`. It
/// is meant to keep documentation free of per-chip pin lists.
///
/// Signals that are not wired to a pad on this chip have to be routed through the GPIO
/// matrix, which can reach any pad. The macro has no pad to return for those, so it accepts
/// an optional fallback to expand to instead. The fallback is not validated.
///
/// If multiple pads provide the signal, the macro returns one that is not reserved for some
/// other purpose, such as booting or interfacing with flash.
///
/// Example usage:
/// - `gpio_for_signal!(ADC1_CH0)`
/// - `gpio_for_signal!(LP_I2C_SDA, "GPIO6")`
#[macro_export]
#[cfg_attr(docsrs, doc(cfg(feature = "_device-selected")))]
macro_rules! gpio_for_signal {
    (XTAL_32K_N $(, $_fallback:literal)?) => {
        "GPIO4"
    };
    (XTAL_32K_P $(, $_fallback:literal)?) => {
        "GPIO5"
    };
    (USJ_DM $(, $_fallback:literal)?) => {
        "GPIO13"
    };
    (USJ_DP $(, $_fallback:literal)?) => {
        "GPIO14"
    };
    (FSPIQ $(, $_fallback:literal)?) => {
        "GPIO15"
    };
    (FSPICLK $(, $_fallback:literal)?) => {
        "GPIO16"
    };
    (FSPID $(, $_fallback:literal)?) => {
        "GPIO17"
    };
    (FSPIWP $(, $_fallback:literal)?) => {
        "GPIO18"
    };
    (FSPIHD $(, $_fallback:literal)?) => {
        "GPIO19"
    };
    (FSPICS0 $(, $_fallback:literal)?) => {
        "GPIO20"
    };
    (U0RXD $(, $_fallback:literal)?) => {
        "GPIO23"
    };
    (U0TXD $(, $_fallback:literal)?) => {
        "GPIO24"
    };
    (MTMS $(, $_fallback:literal)?) => {
        "GPIO28"
    };
    (ADC1_CH0 $(, $_fallback:literal)?) => {
        "GPIO28"
    };
    (MTDI $(, $_fallback:literal)?) => {
        "GPIO29"
    };
    (ADC1_CH1 $(, $_fallback:literal)?) => {
        "GPIO29"
    };
    (MTCK $(, $_fallback:literal)?) => {
        "GPIO30"
    };
    (ADC1_CH2 $(, $_fallback:literal)?) => {
        "GPIO30"
    };
    (MTDO $(, $_fallback:literal)?) => {
        "GPIO31"
    };
    (ADC1_CH3 $(, $_fallback:literal)?) => {
        "GPIO31"
    };
    (ADC1_CH4 $(, $_fallback:literal)?) => {
        "GPIO32"
    };
    ($_signal:ident, $fallback:literal) => {
        $fallback
    };
}
